import json, statistics

base = "/user/user1/harbor-runs/1ed9b3f9d2d6/workspace/logs/recorded_run/validation"
data = {}
for step in [0, 5, 10, 15, 20]:
    rows = [json.loads(l) for l in open(f"{base}/{step}.jsonl")]
    data[step] = rows
    scores = [r["acc"] for r in rows]
    print(f"step {step}: n={len(rows)} acc mean={statistics.mean(scores):.4f}")

# per-uid score evolution
uids = [r["uid"] for r in data[0]]
by_uid = {u: {s: None for s in data} for u in uids}
for s in data:
    for r in data[s]:
        if r["uid"] in by_uid:
            by_uid[r["uid"]][s] = r["acc"]

# transitions
flips = {}
for u, d in by_uid.items():
    seq = [d[s] for s in [0, 5, 10, 15, 20]]
    flips.setdefault(str(seq), []).append(u)
for k in sorted(flips, key=lambda k: -len(flips[k])):
    print(k, len(flips[k]))

# how many final vs initial differ
diff = sum(1 for u, d in by_uid.items() if d[0] != d[20])
print("uids whose acc changed between step0 and step20:", diff)
EOF
