cat > /tmp/diag/leak_check2.py <<'PY'
import pandas as pd, re, hashlib

WS = '/user/user1/harbor-runs/1ed9b3f9d2d6/workspace'
tr = pd.read_parquet(f'{WS}/data/geo3k/train.parquet')
te = pd.read_parquet(f'{WS}/data/geo3k/test.parquet')

def key(row):
    p = row['prompt']
    if isinstance(p, dict): p = str(p)
    p = re.sub(r'\s+', ' ', str(p)).strip().lower()
    return p

def img_hash(row):
    imgs = row['images']
    if imgs is None: return 'NONE'
    if isinstance(imgs, list):
        return hashlib.md5(b''.join(bytes(x) for x in imgs)).hexdigest()
    return hashlib.md5(bytes(imgs)).hexdigest()

def gt(row):
    rm = row['reward_model']
    return str(rm['ground_truth']) if isinstance(rm, dict) and 'ground_truth' in rm else 'NONE'

tr['k'] = tr.apply(key, axis=1); tr['ih'] = tr.apply(img_hash, axis=1); tr['gt'] = tr.apply(gt, axis=1)
te['k'] = te.apply(key, axis=1); te['ih'] = te.apply(img_hash, axis=1); te['gt'] = te.apply(gt, axis=1)

te_by_k = {}
for _, r in te.iterrows():
    te_by_k.setdefault(r['k'], []).append((r['ih'], r['gt']))

same_text = same_text_gt = same_img_gt = 0
for _, r in tr.iterrows():
    if r['k'] in te_by_k:
        same_text += 1
        for ih, g in te_by_k[r['k']]:
            if g == r['gt']:
                same_text_gt += 1
                if ih == r['ih']:
                    same_img_gt += 1
                    break
print(f'train rows whose prompt text also appears in test: {same_text}/{len(tr)}')
print(f'  ...of those with a matching ground_truth too:  {same_text_gt}')
print(f'  ...of those with matching prompt AND gt AND identical image bytes: {same_img_gt}')

# Now compare against the source dataset split to see if this is inherited
import glob
src_tr = f'{WS}/data/geometry3k_source/data'
print('\nsource files:', sorted(glob.glob(f'{src_tr}/*')))
PY
python3 -I /tmp/diag/leak_check2.py

